const fs = require("node:fs");
const path = require("node:path");
const display = require("../data/www/display-editor.js");
const records = new Map();
for (const character of "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789 .-?!:/+")
  records.set(character, display.glyph(character));
for (const [character, record] of Object.entries(display.unicodeFont))
  records.set(character, record.word);
const lines = [
  "/* Generated by scripts/generate_display_font.js; do not edit. */",
  "static const struct { uint32_t codepoint, base, mark; uint64_t word; } text_font[] = {"
];
for (const [character, word] of records) {
  const decomposition = Array.from(character.normalize("NFD"), c => c.codePointAt(0));
  lines.push(`  {0x${character.codePointAt(0).toString(16)}, 0x${decomposition[0].toString(16)}, 0x${(decomposition[1] || 0).toString(16)}, 0x${display.hex(word)}ULL},`);
}
lines.push("};", "static const struct { uint32_t codepoint, base; } text_transliterations[] = {");
for (let cp = 0; cp < 0x110000; ++cp) {
  const character = String.fromCodePoint(cp);
  if (/^\p{Script=Latin}$/u.test(character)) {
    const nfd = character.normalize("NFD");
    if (/^[A-Za-z]\p{Mark}+$/u.test(nfd))
      lines.push(`  {0x${cp.toString(16)}, 0x${nfd.codePointAt(0).toString(16)}},`);
  }
}
lines.push("};", "static const struct { uint32_t first, last; } text_marks[] = {");
let first = -1;
for (let cp = 0; cp <= 0x110000; ++cp) {
  const mark = cp < 0x110000 &&
    /[\p{Mark}\p{Grapheme_Extend}]/u.test(String.fromCodePoint(cp));
  if (mark && first < 0) first = cp;
  if (!mark && first >= 0) {
    lines.push(`  {0x${first.toString(16)}, 0x${(cp - 1).toString(16)}},`);
    first = -1;
  }
}
lines.push("};", "");
fs.writeFileSync(path.join(__dirname, "../main/sony_text_font.inc"), lines.join("\n"));
